  color: var(--text-color);
  margin: 0;
  padding: 0;
}

header {
  padding: 1rem 2rem;
  background-color: var(--primary-color);
  color: white;
  text-align: center;
}

.board {
  display: flex;
  padding: 20px;
  gap: 20px;
  align-items: flex-start;
  overflow-x: auto;
  height: calc(100vh - 100px);
}

.column {
  background-color: var(--column-bg);
  border-radius: var(--border-radius);
  width: 300px;
  min-width: 300px;
  max-height: 100%;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow);
}

.column-header {
  padding: 12px;
  font-weight: bold;
  font-size: 1.1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.cards-container {
  padding: 8px;
  flex-grow: 1;
  overflow-y: auto;
  min-height: 50px;
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
