      const pos2 = rows.find(r => r.id === afterId)?.position;

      if (pos1 !== undefined && pos2 !== undefined) {
        newPosition = (pos1 + pos2) / 2;
      } else {
        // Fallback if one is missing
        newPosition = (pos1 || pos2 || 0) + 0.1;
      }
    } else if (beforeId) {
