  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 12px;
  margin-bottom: 8px;
  box-shadow: var(--shadow);
  cursor: grab;
  user-select: none;
  position: relative;
}

.card:active {
  cursor: grabbing;
}

.card.dragging {
  opacity: 0.5;
