  --bg-color: #f4f5f7;
  --column-bg: #ebecf0;
  --card-bg: #ffffff;
  --text-color: #172b4d;
  --primary-color: #0052cc;
  --border-radius: 4px;
  --shadow: 0 1px 3px rgba(0,0,0,0.12), 0 1px 2px rgba(0,0,0,0.24);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  margin: 0;
  padding: 0;
}

header {
  padding: 1rem 2rem;
  background-color: var(--primary-color);
  color: white;
  text-align: center;
}

.board {
  display: flex;
  padding: 20px;
  gap: 20px;
  align-items: flex-start;
  overflow-x: auto;
  height: calc(100vh - 100px);
}

.column {
  background-color: var(--column-bg);
  border-radius: var(--border-radius);
  width: 300px;
  min-width: 300px;
  max-height: 100%;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow);
}

.column-header {
  padding: 12px;
  font-weight: bold;
  font-size: 1.1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.cards-container {
  padding: 8px;
  flex-grow: 1;
  overflow-y: auto;
  min-height: 50px;
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 12px;
  margin-bottom: 8px;
  box-shadow: var(--shadow);
  cursor: grab;
  user-select: none;
  position: relative;
}

.card:active {
  cursor: grabbing;
}

.card.dragging {
  opacity: 0.5;
}

.add-card-form {
  padding: 8px;
  display: flex;
  gap: 8px;
  border-top: 1px solid #ddd;
}

.add-card-form input {
  flex-grow: 1;
  padding: 6px;
  border: 1px solid #ccc;
  border-radius: var(--border-radius);
}

.add-card-form button {
  padding: 6px 12px;
  background-color: var(--primary-color);
  color: white;
  border: none;
  border-radius: var(--border-radius);
  cursor: pointer;
}

.add-card-form button:hover {
  background-color: #003d99;
}
